demo.program:
// GMAT mission list demo (simulated model)
var m=['LRO','LADEE','OSIRIS-REx','TESS'];
for(var i=0;i<m.length;i++){console.log('GMAT-designed: '+m[i]);}
console.log(m.length+' real missions');

// Adaptive step demo (simulated model)
var r=6578, steps=0;
for(var i=0;i<6;i++){var dt=r>20000?600:60;steps++;r+=5000;console.log('r='+r+'km dt='+dt+'s');}
console.log('propagated with '+steps+' adaptive steps');

// Force model stack demo (simulated model)
var f=['point-mass','J2','drag','SRP','lunar'];
var acc=[8.7,0.01,0.0002,0.00005,0.003];
for(var i=0;i<f.length;i++){console.log(f[i]+': '+acc[i]+' m/s^2');}
console.log(f.length+' forces in the model');

// Finite burn demo (simulated model)
var thrust=400, isp=300, m0=2000, dt=120;
var mdot=thrust/(isp*9.80665), m1=m0-mdot*dt;
var dv=isp*9.80665*Math.log(m0/m1);
console.log('burn '+dt+'s: mass '+m0+'->'+m1.toFixed(1)+'kg');
console.log('delta-v='+dv.toFixed(1)+' m/s (rocket equation)');

// Differential corrector demo (simulated model)
var miss=500, dv=0;
for(var i=0;i<5;i++){var corr=miss*0.002;dv+=corr;miss*=0.15;console.log('iter '+i+': miss='+miss.toFixed(1)+'km dv='+dv.toFixed(3));}
console.log('targeted: total dv='+dv.toFixed(3)+' km/s');

// Batch LS demo (simulated model)
var truth=7000, meas=[7012,6991,7005,6998,7003], s=0;
for(var i=0;i<meas.length;i++){s+=meas[i];}
var est=s/meas.length;
console.log('truth='+truth+' est='+est.toFixed(1)+' err='+(est-truth).toFixed(1)+'km');
console.log('batch fit over '+meas.length+' passes');

// Mission script demo (simulated model)
var script=['Create Spacecraft sat','Create Propagator p','BeginMissionSequence','Propagate p(sat) {sat.ElapsedDays=1}','Maneuver dv'];
for(var i=0;i<script.length;i++){console.log('> '+script[i]);}
console.log(script.length+' script lines = a mission');

// Frame rotation demo (simulated model)
var th=30*Math.PI/180, v=[1,0];
var vr=[v[0]*Math.cos(th)-v[1]*Math.sin(th),v[0]*Math.sin(th)+v[1]*Math.cos(th)];
console.log('inertial ['+v+'] -> rotated ['+vr[0].toFixed(3)+','+vr[1].toFixed(3)+']');
console.log('frame math keeps burns honest');

// Optimizer demo (simulated model)
var best={dv:9e9,x:0};
for(var x=0;x<=10;x+=0.5){var dv=Math.abs(x-6.3)*0.4+2.1;if(dv<best.dv)best={dv:dv,x:x};}
console.log('optimal x='+best.x+' dv='+best.dv.toFixed(2)+' km/s');
console.log('optimizer found the minimum');

// Lunar station-keeping demo (simulated model)
var alt=50, n=4;
for(var i=0;i<n;i++){alt-=3.2;console.log('week '+i+': alt='+alt.toFixed(1)+'km');alt+=3.2;console.log('  maneuver: alt restored');}
console.log(n+' station-keeping cycles');

// Proximity ops demo (simulated model)
var r=1000;
for(var i=0;i<4;i++){r*=0.5;console.log('approach: range='+r+'m');}
console.log('TAG corridor entered (simulated)');

// Resonance demo (simulated model)
var period_moon=27.3, period_tess=13.6;
console.log('TESS period '+period_tess+'d vs Moon '+period_moon+'d');
console.log('ratio '+(period_moon/period_tess).toFixed(2)+' ~ 2:1 resonance');

// Validation demo (simulated model)
var truth=1.0, got=1.003;
var err=Math.abs(got-truth)/truth*100;
console.log('error vs truth: '+err.toFixed(2)+'%');
console.log(err<1?'VALIDATED':'FAILED');

// Ephemeris lookup demo (simulated model)
var bodies=['Earth','Moon','Mars'];
var pos=[[0,0,0],[384400,0,0],[2.28e8,0,0]];
for(var i=0;i<bodies.length;i++){console.log(bodies[i]+' @ '+pos[i][0]+' km');}
console.log('one ephemeris, consistent solar system');

// GMAT loop demo (simulated model)
var loop=['sketch','script','propagate','target','optimize','estimate','validate','fly'];
for(var i=0;i<loop.length;i++){console.log((i+1)+'. '+loop[i]);}
console.log('mission design loop closed');
